// apply-beranda2.mjs - beranda HP native: Premium Elegant bertema biru indigo (sama dengan web).
// Menulis 8 berkas HP (termasuk bottom nav iOS dan Android bertema indigo) dan menghapus berkas lama yang tidak dipakai lagi
// dan mengubah 1 kata di landing/package-card.tsx (export themes).
// Semua pemeriksaan jalan SEBELUM ada berkas yang ditulis. Aman dijalankan dua kali.
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const J = (p) => path.join(ROOT, p);
const fail = (m) => { console.error('BERHENTI, tidak ada yang diubah: ' + m); process.exit(1); };
const has = (p) => ['', '.ts', '.tsx'].some((e) => fs.existsSync(J(p + e)) && fs.statSync(J(p + e)).isFile());

const FILES = {
 "resources/js/components/mobile/kit/soft.ts": "",
 "resources/js/components/mobile/kit/list-row.tsx": "",
 "resources/js/components/mobile/kit/segments.tsx": "",
 "resources/js/components/mobile/kit/poster-card.tsx": "",
 "resources/js/components/mobile/home/panels.tsx": "",
 "resources/js/components/mobile/pages/home-mobile.tsx": "",
 "resources/js/components/mobile/ios/bottom-nav.tsx": "",
 "resources/js/components/mobile/android/bottom-nav.tsx": ""
};
const decode = (b64) => Buffer.from(b64, 'base64').toString('utf8');
const mobile = 'resources/js/components/mobile/';

// 1) berkas yang harus sudah ada
for (const need of [
  mobile + 'pages/home-mobile.tsx', mobile + 'kit/poster-card.tsx', mobile + 'bottom-nav.tsx', mobile + 'use-platform',
  mobile + 'ios/bottom-nav.tsx', mobile + 'android/bottom-nav.tsx', mobile + 'nav-types.ts', mobile + 'nav-utils', mobile + 'use-typing',
  'resources/js/hooks/use-theme', 'resources/js/components/user/avatar', 'resources/js/components/user/notification-bell',
  'resources/js/components/landing/package-card.tsx', 'resources/js/components/landing/ticket-card-vertical',
  'resources/js/components/landing/event-section.tsx',
]) if (!has(need)) fail('tidak ada ' + need + ' (jalankan dari ~/Projects/simpleindonesia)');

// 2) beranda lama harus memang HomeMobile
const oldHome = fs.readFileSync(J(mobile + 'pages/home-mobile.tsx'), 'utf8');
if (!oldHome.includes('export default function HomeMobile')) fail('home-mobile.tsx lama tidak berisi HomeMobile');

// 2b) bottom nav lama harus memang tampilan nav (dua berkas ini saya timpa)
for (const [rel, name] of [[mobile + 'ios/bottom-nav.tsx', 'IosBottomNav'], [mobile + 'android/bottom-nav.tsx', 'AndroidBottomNav']]) {
  const c = fs.readFileSync(J(rel), 'utf8');
  if (!c.includes('export default function ' + name) || !c.includes('NavViewProps')) fail(rel + ' tidak berbentuk seperti yang diharapkan (' + name + ')');
}

// 3) poster-card baru harus tetap mengekspor semua yang diekspor berkas lama
const oldCard = fs.readFileSync(J(mobile + 'kit/poster-card.tsx'), 'utf8');
const newCard = decode(FILES[mobile + 'kit/poster-card.tsx']);
const names = [...oldCard.matchAll(/^export (?:default )?(?:function|const|type|interface) (\w+)/gm)].map((m) => m[1]);
if (!names.length) fail('poster-card.tsx lama tidak punya export, kirim berkasnya ke saya');
for (const n of names) if (!new RegExp('export (?:default )?(?:function|const|type|interface) ' + n + '\\b').test(newCard)) fail('poster-card baru tidak mengekspor ' + n);

// 4) package-card: export themes (satu kata)
const PC = J('resources/js/components/landing/package-card.tsx');
let pc = fs.readFileSync(PC, 'utf8');
const A = 'const themes: Record<string, Theme> = {';
const B = 'export const themes: Record<string, Theme> = {';
const pcDone = pc.includes(B);
if (!pcDone) {
  if (pc.split(A).length !== 2) fail('package-card.tsx: pola themes tidak cocok');
  pc = pc.replace(A, () => B);
}

// 5) peringatan lunak: bentuk useTheme
const ut = ['.ts', '.tsx'].map((e) => J('resources/js/hooks/use-theme' + e)).find((f) => fs.existsSync(f));
if (ut) { const s = fs.readFileSync(ut, 'utf8'); if (!/\bdark\b/.test(s) || !/\btoggle\b/.test(s)) console.warn('PERINGATAN: use-theme tidak terlihat mengembalikan { dark, toggle }. Jalankan npm run types:check.'); }

// 5b) berkas buatan kita sebelumnya yang kini yatim: hapus hanya kalau cocok penanda dan tidak diimpor berkas lain
const OBSOLETE = {
  [mobile + 'kit/section-heading.tsx']: 'STRIP',
  [mobile + 'home/ticket-strip.tsx']: 'TicketStrip',
  [mobile + 'home/package-strip.tsx']: 'PackageStrip',
  [mobile + 'home/news-list.tsx']: 'NewsList',
};
const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? (e.name === 'node_modules' ? [] : walk(path.join(d, e.name))) : [path.join(d, e.name)]));
const skip = new Set([...Object.keys(FILES), ...Object.keys(OBSOLETE)].map(J));
const others = walk(J('resources/js')).filter((f) => /\.(tsx?|jsx?)$/.test(f) && !skip.has(f)).map((f) => fs.readFileSync(f, 'utf8'));
const toDelete = [];
for (const [rel, marker] of Object.entries(OBSOLETE)) {
  if (!fs.existsSync(J(rel))) continue;
  const base = path.basename(rel).replace(/\.tsx?$/, '');
  const used = others.some((c) => new RegExp("from ['\"][^'\"]*/" + base + "['\"]").test(c));
  if (!fs.readFileSync(J(rel), 'utf8').includes(marker)) { console.warn('DILEWATI (bukan buatan kita): ' + rel); continue; }
  if (used) { console.warn('DIPERTAHANKAN (masih diimpor berkas lain): ' + rel); continue; }
  toDelete.push(rel);
}

// 6) tulis
let wrote = 0;
for (const [dest, b64] of Object.entries(FILES)) {
  const content = decode(b64);
  const target = J(dest);
  if (fs.existsSync(target) && fs.readFileSync(target, 'utf8') === content) continue;
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content);
  wrote++;
}
if (!pcDone) fs.writeFileSync(PC, pc);
for (const rel of toDelete) fs.unlinkSync(J(rel));
console.log('OK: ' + wrote + ' berkas ditulis' + (wrote === 0 ? ' (sudah terpasang)' : '') + ', ' + toDelete.length + ' berkas lama dihapus, package-card.tsx ' + (pcDone ? 'sudah' : 'diubah') + '.');
